    async with async_playwright() as p:
        browser = await p.chromium.launch(headless=True, args=['--no-sandbox','--disable-gpu','--disable-dev-shm-usage'])
        page = await browser.new_page(viewport={'width': 900, 'height': 1400})
        await page.goto('file:///app/output/open-source-contributor-index-infographic.html', wait_until='networkidle')
        await asyncio.sleep(4)

        # Check rendered content
        info = await page.evaluate('''() => {
            const container = document.getElementById(\"container\");
            const canvas = document.querySelector(\"canvas\");
            const svg = document.querySelector(\"svg\");
            const children = container ? container.childElementCount : 0;
            return {
                containerHTML: container ? container.innerHTML.substring(0, 200) : \"no container\",
                canvasCount: document.querySelectorAll(\"canvas\").length,
                svgCount: document.querySelectorAll(\"svg\").length,
                bodySize: document.body.scrollHeight,
                containerRect: container ? JSON.stringify(container.getBoundingClientRect()) : \"none\"
            };
        }''')
        print('Info:', info)
        await browser.close()

asyncio.run(inspect())
